"""Input-only dynamic enrichment of the elastic modal subspace.

Residual-displacement snapshots are generated by the reduced physical model,
never from FEM transient labels. Galerkin integration replaces their static
addition, restoring inertia in the important high-frequency spatial patterns.
"""
import time
import numpy as np
from scipy.linalg import eigh
from solid.mesh import nodal_load
from .response import response
from .propagator import linear_force_oscillators

def enrich(mesh,scene,basis,step_us=.025,count=96):
    started=time.monotonic();pilot=response(mesh,scene,basis,step_us,True,linear_force_oscillators);m=basis['mass'];root=np.sqrt(m);phi=basis['phi'];v=root[:,None]*phi;load,_=nodal_load(mesh,scene['source']);linear=basis['residual_flexibility'](load.reshape(-1,1));columns=[linear]
    indices=np.unique(np.linspace(0,len(pilot['times_us'])-1,64,dtype=int))
    for branch in pilot['static_basis_responses']:
        block=branch[indices].T;scale=np.linalg.norm((basis['stiffness']@block)/root[:,None])
        if scale>0:columns.append(block/scale)
    columns[0]=linear/max(np.linalg.norm((basis['stiffness']@linear)/root[:,None]),1e-100);snapshots=root[:,None]*np.concatenate(columns,axis=1);snapshots-=v@(v.T@snapshots);force_snapshots=(basis['stiffness']@(snapshots/root[:,None]))/root[:,None];_,s,right=np.linalg.svd(force_snapshots,full_matrices=False);rank=min(count,int(np.sum(s>s[0]*1e-10)));extra=snapshots@right[:rank].T;extra-=v@(v.T@extra);free=~basis['fixed'];orthogonal,_=np.linalg.qr(extra[free]);extra[:]=0.;extra[free]=orthogonal;combined=np.column_stack([v,extra])/root[:,None];reduced=combined.T@(basis['stiffness']@combined)*1e-12;reduced=(reduced+reduced.T)*.5;values,rotation=eigh(reduced);values[np.abs(values)<1e-7]=0.
    if values.min()<-1e-7:raise ValueError('Enriched stiffness lost positivity.')
    new_phi=combined@rotation;gradient=np.einsum('eaim,eaj->eijm',new_phi.reshape(-1,3,len(values))[mesh['tetra']],mesh['grad']);result=dict(basis);result.update(phi=new_phi,gradient=gradient,lambda_us2=values,frequency_mhz=np.sqrt(values)/(2*np.pi),dynamic_enrichment={'vectors':rank,'snapshot_times':len(indices),'retained_force_snapshot_energy':float(np.sum(s[:rank]**2)/np.sum(s**2)),'input_only':True,'uses_transient_labels':False,'seconds':time.monotonic()-started},preparation_seconds=basis['preparation_seconds']+time.monotonic()-started)
    return result
